<?php
namespace App\Http\Controllers\Provider;use App\Http\Controllers\Controller;use App\Http\Requests\ServiceRequest;use App\Models\Category;use Illuminate\Support\Str;use Illuminate\Support\Facades\Storage;use App\Models\Service;
class ServiceController extends Controller{public function index(){return view('provider.services.index',['services'=>auth()->user()->services()->with('category')->latest()->paginate(15),'categories'=>Category::where('is_active',true)->get()]);}public function store(ServiceRequest $r){$d=$r->validated();$d['provider_id']=auth()->id();$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));if($r->hasFile('image'))$d['image']=$r->file('image')->store('services','public');Service::create($d);return back()->with('success','Service created.');}public function update(ServiceRequest $r,Service $service){abort_unless($service->provider_id===auth()->id(),403);$d=$r->validated();if($r->hasFile('image')){$old=$service->image;if($old)Storage::disk('public')->delete($old);$d['image']=$r->file('image')->store('services','public');}$service->update($d);return back()->with('success','Service updated.');}public function destroy(Service $service){abort_unless($service->provider_id===auth()->id(),403);$service->delete();return back()->with('success','Service deleted.');}}
